package com.nigson.experience.distributor;

import com.nigson.shared.events.EventCodec;import com.nigson.shared.security.PrivateWorkload;import com.sun.net.httpserver.HttpServer;import java.net.*;import java.net.http.*;import java.time.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;
class DistributorEntitlementHttpClientTest {
 @Test void api117UsesExactWorkloadRouteAndStableCommandAfterTimeoutAfterAcceptance()throws Exception{var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);UUID command=UUID.randomUUID(),application=UUID.randomUUID(),party=UUID.randomUUID(),organization=UUID.randomUUID(),market=UUID.randomUUID(),book=UUID.randomUUID(),correlation=UUID.randomUUID();AtomicInteger calls=new AtomicInteger();server.createContext("/internal/v1/distributor-entitlements",x->{int call=calls.incrementAndGet();byte[] request=x.getRequestBody().readAllBytes();assertThat(x.getRequestHeaders().getFirst("Authorization")).isEqualTo("Bearer local-api117-token");assertThat(x.getRequestHeaders().getFirst("If-Match")).isEqualTo("\"0\"");assertThat(x.getRequestHeaders().getFirst("Idempotency-Key")).isEqualTo("stable-command-key");assertThat(EventCodec.JSON.readTree(request).path("commandId").asString()).isEqualTo(command.toString());byte[] body=EventCodec.JSON.writeValueAsBytes(Map.of("commandId",command,"organizationId",organization,"state","ACTIVE","revision",0));if(call==1){try{Thread.sleep(6000);}catch(InterruptedException e){Thread.currentThread().interrupt();}try{x.sendResponseHeaders(200,body.length);x.getResponseBody().write(body);}catch(Exception ignored){}finally{x.close();}}else{x.getResponseHeaders().set("Content-Type","application/json");x.getResponseHeaders().set("ETag","\"0\"");x.sendResponseHeaders(200,body.length);x.getResponseBody().write(body);x.close();}});server.start();try{var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-117")).findFirst().orElseThrow();var client=new DistributorEntitlementHttpClient(URI.create("http://127.0.0.1:"+server.getAddress().getPort()),r->{assertThat(r).isEqualTo(route);return "local-api117-token";},HttpClient.newHttpClient());var request=new DistributorService.EntitlementCommand(command,application,party,"Synthetic organization","NG","REF-1","ACTIVATE",market,book,0,"stable-command-key",correlation);assertThatThrownBy(()->client.execute(request)).isInstanceOf(com.nigson.shared.problem.Problem.Failure.class);var ack=client.execute(request);assertThat(ack).isEqualTo(new DistributorService.EntitlementAck(command,organization,"ACTIVE",0));assertThat(calls).hasValue(2);}finally{server.stop(0);}}
}
